import * as React from "react";

export type DiscountSlashIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function DiscountSlashIcon({ size = 20, ...props }: DiscountSlashIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <path d="M5 19 19 5" />
      <circle cx={8} cy={8} r={3} />
      <circle cx={16} cy={16} r={3} />
    </svg>
  );
}
